"use client"

import animation from "react-useanimations/lib/moreHorizontal"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "More Horizontal" from https://useanimations.com (MIT): https://useanimations.com/icons/more-horizontal
export function AnimatedMoreHorizontal(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="loop"
      {...props}
    />
  )
}
